// ================================================================
// PREPARE INPUT — Load dynamic config from DB, resolve personality
// ================================================================
const body = $input.item.json.body || {};
const query = body.message || body.query || body.text || '';
const channelSlug = body.channel || 'default';
const visitorId = body.visitor_id || body.session_id || 'anon-' + Date.now();

if (!query) {
  return { json: { error: 'Missing message in request body', status: 400 } };
}

// 1. Load channel config from DB
const supabaseUrl = $env?.AISHA_POSTGREST_URL || ($env?.AISHA_POSTGREST_URL || '');
const serviceKey = $env?.AISHA_POSTGREST_SERVICE_KEY || '';

const configRes = await fetch(
  `${supabaseUrl}/rest/v1/rpc/get_active_channel_config`,
  {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'apikey': serviceKey,
      'Authorization': `Bearer ${serviceKey}`,
    },
    body: JSON.stringify({ p_channel_slug: channelSlug }),
  }
);
const channelConfig = await configRes.json();

if (channelConfig?.error) {
  return { json: { error: channelConfig.error, status: 404 } };
}

// 2. Get or create session
const sessionRes = await fetch(
  `${supabaseUrl}/rest/v1/rpc/get_or_create_public_chat_session`,
  {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'apikey': serviceKey,
      'Authorization': `Bearer ${serviceKey}`,
    },
    body: JSON.stringify({
      p_channel_id: channelConfig.channel_id,
      p_visitor_id: visitorId,
      p_metadata: body.visitor_metadata || {},
    }),
  }
);
const session = await sessionRes.json();

// 3. Record user message
await fetch(
  `${supabaseUrl}/rest/v1/rpc/record_public_chat_message`,
  {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'apikey': serviceKey,
      'Authorization': `Bearer ${serviceKey}`,
    },
    body: JSON.stringify({
      p_session_id: session.session_id,
      p_role: 'user',
      p_content: query,
      p_metadata: { source: body.source || 'api', channel: channelSlug },
    }),
  }
);

// 4. Resolve personality context (if enabled)
let personalityBlock = '';
if (channelConfig.personality_enabled) {
  try {
    const mcpUrl = `${supabaseUrl}/functions/v1/mcp-knowledge-server`;
    const mcpToken = $env?.AISHA_ACCESS_TOKEN || $env?.AISHA_KEYCLOAK_ACCESS_TOKEN || '';
    const personalityRes = await fetch(mcpUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${mcpToken}`,
      },
      body: JSON.stringify({
        jsonrpc: '2.0',
        id: Date.now(),
        method: 'tools/call',
        params: {
          name: 'compose_context',
          arguments: {
            profile: channelConfig.context_profile || 'public_chat',
            task_kind: 'public_chat',
            include_personality: true,
          },
        },
      }),
    });
    const pResult = await personalityRes.json();
    if (pResult?.result?.content?.[0]?.text) {
      const ctx = JSON.parse(pResult.result.content[0].text);
      personalityBlock = ctx.personality_context || '';
    }
  } catch (e) {
    // Personality is optional — continue without it
  }
}

// 5. Build dynamic system prompt
const guardrails = channelConfig.guardrails || {};
const guardrailsBlock = `
## Guardrails
- Max response length: concise, under 300 words
- Blocked topics: ${(guardrails.blocked_topics || []).join(', ') || 'none'}
- PII redaction: ${guardrails.pii_redaction ? 'enabled' : 'disabled'}
- External links: ${guardrails.allow_external_links ? 'allowed' : 'not allowed'}
- Languages: ${(guardrails.allowed_languages || ['cs', 'en']).join(', ')}
`;

const systemPrompt = [
  personalityBlock,
  channelConfig.system_prompt || '',
  guardrailsBlock,
  '\n## Context\nYou are responding to a public visitor on the ' + channelConfig.display_name + ' channel.',
  '\nRespond in the language the visitor uses. Be helpful, friendly, and concise.',
].filter(Boolean).join('\n\n');

// 6. Build conversation history for context
const history = (session.messages || []).map(m => ({
  role: m.role,
  content: m.content,
}));

return {
  json: {
    chatInput: query,
    systemPrompt,
    session_id: session.session_id,
    channel_config: channelConfig,
    history,
    metadata: {
      source: body.source || 'api',
      channel: channelSlug,
      visitor_id: visitorId,
      timestamp: new Date().toISOString(),
    },
  },
};

// ================================================================
// ROUTING GATE — Check routing rules and decide agent path
// ================================================================
const input = $input.item.json;
const config = input.channel_config || {};
const rules = config.routing_rules?.rules || [];
const query = (input.chatInput || '').toLowerCase();
const guardrails = config.guardrails || {};

// Check rate limiting (basic — production should use Redis)
// For now, trust the edge function to handle rate limiting

// Check escalation keywords
const escalationKeywords = guardrails.escalation_keywords || [];
const shouldEscalate = escalationKeywords.some(kw => query.includes(kw.toLowerCase()));

// Check routing rules
let delegateTo = null;
let routeReason = 'default';

if (shouldEscalate) {
  delegateTo = 'WF_DIRIGENT_AGENT';
  routeReason = 'escalation_keyword';
} else {
  for (const rule of rules) {
    if (rule.trigger === 'knowledge_query' && (
      query.includes('jak') || query.includes('co je') || 
      query.includes('how') || query.includes('what is') ||
      query.includes('explain') || query.includes('vysvětli')
    )) {
      delegateTo = rule.delegate_to;
      routeReason = 'knowledge_query';
      break;
    }
    if (rule.trigger === 'product_inquiry' && (
      query.includes('produkt') || query.includes('product') ||
      query.includes('cena') || query.includes('price') ||
      query.includes('objednat') || query.includes('order')
    )) {
      delegateTo = rule.delegate_to;
      routeReason = 'product_inquiry';
      break;
    }
  }
}

return {
  json: {
    ...input,
    routing: {
      delegate_to: delegateTo,
      reason: routeReason,
      should_escalate: shouldEscalate,
    },
  },
};

// ================================================================
// FORMAT RESPONSE — Record assistant message, build API response
// ================================================================
const agentOutput = $input.item.json;
const response = agentOutput.output || agentOutput.text || JSON.stringify(agentOutput);

// Get metadata from previous nodes
const allItems = $('Routing Gate').all();
const meta = allItems?.[0]?.json || {};
const sessionId = meta.session_id;
const channelConfig = meta.channel_config || {};
const routing = meta.routing || {};

// Record assistant message
const supabaseUrl = $env?.AISHA_POSTGREST_URL || ($env?.AISHA_POSTGREST_URL || '');
const serviceKey = $env?.AISHA_POSTGREST_SERVICE_KEY || '';

if (sessionId) {
  await fetch(
    `${supabaseUrl}/rest/v1/rpc/record_public_chat_message`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'apikey': serviceKey,
        'Authorization': `Bearer ${serviceKey}`,
      },
      body: JSON.stringify({
        p_session_id: sessionId,
        p_role: 'assistant',
        p_content: response,
        p_metadata: {
          model: channelConfig.model,
          routing: routing.reason,
          channel: channelConfig.slug,
        },
      }),
    }
  );
}

// Capture personality signal (fire-and-forget)
if (channelConfig.personality_enabled) {
  try {
    const mcpUrl = `${supabaseUrl}/functions/v1/mcp-knowledge-server`;
    const mcpToken = $env?.AISHA_ACCESS_TOKEN || $env?.AISHA_KEYCLOAK_ACCESS_TOKEN || '';
    // Detect basic signals
    const userMsg = (meta.chatInput || '').toLowerCase();
    let signalType = 'engagement_burst';
    if (userMsg.includes('děkuj') || userMsg.includes('thank') || userMsg.includes('super')) signalType = 'gratitude';
    if (userMsg.includes('nefunguje') || userMsg.includes('broken') || userMsg.includes('error')) signalType = 'frustration';

    fetch(mcpUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${mcpToken}`,
      },
      body: JSON.stringify({
        jsonrpc: '2.0',
        id: Date.now(),
        method: 'tools/call',
        params: {
          name: 'capture_personality_signal',
          arguments: {
            signal_type: signalType,
            context: `public_chat:${channelConfig.slug}`,
          },
        },
      }),
    }).catch(() => {}); // fire-and-forget
  } catch (e) { /* ignore */ }
}

return {
  json: {
    success: true,
    session_id: sessionId,
    response,
    channel: channelConfig.slug || 'unknown',
    routing: routing.reason || 'default',
    timestamp: new Date().toISOString(),
  },
};

// MCP Tool: search_knowledge (public-scoped)
const query = $input.item.json.query || $input.item.json || '';
let args;
try {
  args = typeof query === 'string' ? JSON.parse(query) : query;
} catch {
  args = typeof query === 'string' && query.length > 0 ? { query } : {};
}

const mcpUrl = ($env?.AISHA_POSTGREST_URL || '') + '/functions/v1/mcp-knowledge-server';
const token = $env?.AISHA_ACCESS_TOKEN || $env?.AISHA_KEYCLOAK_ACCESS_TOKEN || '';

const res = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${token}`,
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'tools/call',
    params: {
      name: 'search_knowledge',
      arguments: {
        query: args.query || '',
        category: args.category || undefined,
        limit: Math.min(args.limit || 10, 20),
        visibility: 'public',
      },
    },
  }),
});

const result = await res.json();
const content = result?.result?.content?.[0]?.text || JSON.stringify(result);
return content;

// MCP Tool: search_ragnarok (public-scoped)
const query = $input.item.json.query || $input.item.json || '';
let args;
try {
  args = typeof query === 'string' ? JSON.parse(query) : query;
} catch {
  args = typeof query === 'string' && query.length > 0 ? { query } : {};
}

const mcpUrl = ($env?.AISHA_POSTGREST_URL || '') + '/functions/v1/mcp-knowledge-server';
const token = $env?.AISHA_ACCESS_TOKEN || $env?.AISHA_KEYCLOAK_ACCESS_TOKEN || '';

const res = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${token}`,
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'tools/call',
    params: {
      name: 'search_ragnarok',
      arguments: {
        query: args.query || '',
        limit: Math.min(args.limit || 5, 10),
      },
    },
  }),
});

const result = await res.json();
const content = result?.result?.content?.[0]?.text || JSON.stringify(result);
return content;

// MCP Tool: get_knowledge_item
const query = $input.item.json.query || $input.item.json || '';
let args;
try {
  args = typeof query === 'string' ? JSON.parse(query) : query;
} catch {
  args = typeof query === 'string' && query.length > 0 ? { slug: query } : {};
}

const mcpUrl = ($env?.AISHA_POSTGREST_URL || '') + '/functions/v1/mcp-knowledge-server';
const token = $env?.AISHA_ACCESS_TOKEN || $env?.AISHA_KEYCLOAK_ACCESS_TOKEN || '';

const res = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${token}`,
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'tools/call',
    params: {
      name: 'get_knowledge_item',
      arguments: args,
    },
  }),
});

const result = await res.json();
const content = result?.result?.content?.[0]?.text || JSON.stringify(result);
return content;
